use std::sync::Arc;
use anyhow::{ensure,Result};
use near_api::{Account,AccountId,Contract,NearGas,NearToken,NetworkConfig,Signer,Transaction};
use near_api::types::transaction::actions::{Action,FunctionCallAction,TransferAction};
use serde_json::{json,Value};
async fn view(c:&Contract,m:&str,a:Value,n:&NetworkConfig)->Result<Value>{let x:near_api::types::Data<Value>=c.call_function(m,a).read_only().fetch_from(n).await?;Ok(x.data)}
async fn call(c:&Contract,m:&str,a:Value,id:&AccountId,s:Arc<Signer>,n:&NetworkConfig,dep:u128,gas:u64)->Result<(bool,u64)>{let r=c.call_function(m,a).transaction().gas(NearGas::from_tgas(gas)).deposit(NearToken::from_yoctonear(dep)).with_signer(id.clone(),s).send_to(n).await?.into_full().ok_or_else(||anyhow::anyhow!("not final"))?; Ok((r.is_success(),r.total_gas_burnt.as_gas()))}
async fn deploy(id:AccountId,bytes:Vec<u8>,args:Value,s:Arc<Signer>,n:&NetworkConfig)->Result<()> {let r=Contract::deploy(id).use_code(bytes).with_init_call("new",args)?.gas(NearGas::from_tgas(300)).with_signer(s).send_to(n).await?.into_full().ok_or_else(||anyhow::anyhow!("not final"))?;ensure!(r.is_success(),"deploy failed {r:?}");Ok(())}
#[tokio::main] async fn main()->Result<()> {
 let sandbox=near_sandbox::Sandbox::start_sandbox_with_version("2.14.0").await?;let n=NetworkConfig::from_rpc_url("sandbox",sandbox.rpc_addr.parse()?);let s=Signer::from_secret_key(near_sandbox::config::DEFAULT_GENESIS_ACCOUNT_PRIVATE_KEY.parse()?)?;
 let org:AccountId="organizer.testnet".parse()?;let eid:AccountId="escrow.testnet".parse()?;let ftid:AccountId="usdc.testnet".parse()?;let mid:AccountId="earn.testnet".parse()?;
 for id in [&org,&eid,&ftid,&mid]{let amount=if id==&eid && std::env::var_os("CAPACITY_TOPUP_ONLY").is_some() {NearToken::from_near(3)} else {NearToken::from_near(30)};sandbox.create_account(id.as_str().parse()?).initial_balance(amount).send().await?;}
 let leaf=std::fs::read(std::env::var("SHOWSTAKE_WASM")?)?;let ftwasm=std::fs::read(std::env::var("FT_WASM")?)?;let mock=std::fs::read(std::env::var("MOCK_WASM")?)?;
 deploy(ftid.clone(),ftwasm,json!({"owner_id":org,"total_supply":"500000000","metadata":{"spec":"ft-1.0.0","name":"Mock USDC","symbol":"USDC","icon":null,"reference":null,"reference_hash":null,"decimals":6}}),s.clone(),&n).await?;
 deploy(mid.clone(),mock,json!({"token":ftid,"controller":org}),s.clone(),&n).await?;
 deploy(eid.clone(),leaf,json!({"organizer":org,"provider_account":mid,"canonical_ft":ftid,"token_symbol":"USDC","token_name":"Mock USDC","token_decimals":6,"provider_kind":"MOCK_TESTNET"}),s.clone(),&n).await?;
 let ft=Contract(ftid.clone());let escrow=Contract(eid.clone());
 if std::env::var_os("CAPACITY_TOPUP_ONLY").is_some() {
   let drain=Transaction::construct(eid.clone(),org.clone()).add_action(Action::Transfer(TransferAction{deposit:NearToken::from_millinear(700)})).with_signer(s.clone()).send_to(&n).await?.into_full().ok_or_else(||anyhow::anyhow!("not final"))?;ensure!(drain.is_success(),"bootstrap drain failed");
   let before=Account(eid.clone()).view().fetch_from(&n).await?;let now=view(&escrow,"get_block_timestamp_ms",json!({}),&n).await?.as_u64().unwrap();
   let rules=json!({"event_id":"e".repeat(128),"title":"t".repeat(256),"location":"l".repeat(512),"rules_text":"r".repeat(8192),"finalize_deadline":now+1_800_000,"deposit":"2000000","capacity":200,"reg_open":now,"reg_close":now+1_200_000,"checkin_open":now+1_200_000,"checkin_close":now+1_210_000});
   let batch=Transaction::construct(org.clone(),eid.clone()).add_action(Action::Transfer(TransferAction{deposit:NearToken::from_near(5)})).add_action(Action::FunctionCall(Box::new(FunctionCallAction{method_name:"create_event".into(),args:serde_json::to_vec(&json!({"rules":rules}))?,gas:NearGas::from_tgas(100),deposit:NearToken::from_yoctonear(0)}))).with_signer(s.clone()).send_to(&n).await?.into_full().ok_or_else(||anyhow::anyhow!("not final"))?;
   let after=Account(eid.clone()).view().fetch_from(&n).await?;let ev=view(&escrow,"get_event",json!({}),&n).await?;ensure!(batch.is_success()&&!ev.is_null(),"batch failed {batch:?}");
   println!("{}",json!({"status":"PASS_LOCAL","scope":"sandbox only; near-factory initial child funding after controlled native bootstrap transfer, single Transfer plus create_event batch","initial_account":before.data,"after_batch":after.data,"gas_burnt":batch.total_gas_burnt.as_gas(),"event":ev}));return Ok(());
 }

 for id in [&eid,&mid]{let(ok,_)=call(&ft,"storage_deposit",json!({"account_id":id}),&org,s.clone(),&n,10_000_000_000_000_000_000_000,40).await?;ensure!(ok,"FT storage failed");}
 let mut users=Vec::new();for i in 0..200 {let name=format!("u{:055}.testnet",i); let id:AccountId=name.parse()?; sandbox.create_account(name.parse()?).initial_balance(NearToken::from_near(1)).send().await?;users.push(id);}
 // Batch normal FT registration and FT transfers; each action is a real receipt.
 for chunk in users.chunks(15){let mut tx=Transaction::construct(org.clone(),ftid.clone());for id in chunk {tx=tx.add_action(Action::FunctionCall(Box::new(FunctionCallAction{method_name:"storage_deposit".into(),args:serde_json::to_vec(&json!({"account_id":id}))?,gas:NearGas::from_tgas(8),deposit:NearToken::from_yoctonear(10_000_000_000_000_000_000_000)}))).add_action(Action::FunctionCall(Box::new(FunctionCallAction{method_name:"ft_transfer".into(),args:serde_json::to_vec(&json!({"receiver_id":id,"amount":"2000000"}))?,gas:NearGas::from_tgas(8),deposit:NearToken::from_yoctonear(1)})));}let r=tx.with_signer(s.clone()).send_to(&n).await?.into_full().ok_or_else(||anyhow::anyhow!("not final"))?;ensure!(r.is_success(),"fund batch failed: {r:?}");}
 let now=view(&escrow,"get_block_timestamp_ms",json!({}),&n).await?.as_u64().unwrap();let event_id="e".repeat(128);let close=now+300_000;let rules=json!({"event_id":event_id,"title":"t".repeat(256),"location":"l".repeat(512),"rules_text":"r".repeat(8192),"finalize_deadline":close+600_000,"deposit":"2000000","capacity":200,"reg_open":now,"reg_close":close,"checkin_open":close,"checkin_close":close+10_000});
 let before=Account(eid.clone()).view().fetch_from(&n).await?;
 let batch=Transaction::construct(org.clone(),eid.clone()).add_action(Action::Transfer(TransferAction{deposit:NearToken::from_near(5)})).add_action(Action::FunctionCall(Box::new(FunctionCallAction{method_name:"create_event".into(),args:serde_json::to_vec(&json!({"rules":rules}))?,gas:NearGas::from_tgas(100),deposit:NearToken::from_yoctonear(0)}))).with_signer(s.clone()).send_to(&n).await?.into_full().ok_or_else(||anyhow::anyhow!("not final"))?;ensure!(batch.is_success(),"topup/create batch failed: {batch:?}");
 let initial=Account(eid.clone()).view().fetch_from(&n).await?;let mut samples=Vec::new();
 for (i,id) in users.iter().enumerate(){let commitment=format!("{:0<128}",format!("c{i:03}"));let msg=json!({"version":1,"event_id":event_id,"commitment_id":commitment}).to_string();let(ok,gas)=call(&ft,"ft_transfer_call",json!({"receiver_id":eid,"amount":"2000000","msg":msg}),id,s.clone(),&n,1,100).await?;ensure!(ok,"deposit failed {i}");if [0,4,199].contains(&i){let v=view(&escrow,"get_event",json!({}),&n).await?;let a=Account(eid.clone()).view().fetch_from(&n).await?;samples.push(json!({"count":i+1,"storage_bytes":a.data.storage_usage,"accepted_principal":v["accepted_principal"],"gas":gas}));}if i%25==0{eprintln!("registration {}",i+1);}}
 let ev=view(&escrow,"get_event",json!({}),&n).await?;ensure!(ev["accepted_principal"]=="400000000","not 200 real deposits: {ev}");
 eprintln!("CAPACITY_SAMPLES {}",json!({"initial_account":before.data,"after_create":initial.data,"samples":samples,"accepted_principal":ev["accepted_principal"]}));
 let mut t=view(&escrow,"get_block_timestamp_ms",json!({}),&n).await?.as_u64().unwrap();for _ in 0..12 {if t>=close {break;}sandbox.fast_forward((((close-t)/300)+50).min(500)).await?;t=view(&escrow,"get_block_timestamp_ms",json!({}),&n).await?.as_u64().unwrap();}ensure!(t>=close,"fast-forward failed time {t} target {close}");
 let(ok,_)=call(&escrow,"close_registration",json!({}),&org,s.clone(),&n,0,100).await?;ensure!(ok,"close failed");let(ok,_)=call(&escrow,"trigger_earn_supply",json!({}),&org,s.clone(),&n,0,300).await?;ensure!(ok,"supply transaction failed");let ev=view(&escrow,"get_event",json!({}),&n).await?;ensure!(ev["earn_state"]=="Supplied","supply incomplete {ev}");
 t=view(&escrow,"get_block_timestamp_ms",json!({}),&n).await?.as_u64().unwrap();for _ in 0..12 {if t>=close+10_000 {break;}sandbox.fast_forward(((((close+10_000)-t)/300)+50).min(500)).await?;t=view(&escrow,"get_block_timestamp_ms",json!({}),&n).await?.as_u64().unwrap();}ensure!(t>=close+10_000,"checkin time not reached");
 let(final_ok,final_gas)=call(&escrow,"finalize_attendance",json!({}),&org,s.clone(),&n,0,300).await?;if !final_ok {println!("{}",json!({"status":"FAILED","reason":"finalize over gas or failed","samples":samples,"finalize_gas":final_gas}));anyhow::bail!("finalize failed");}
 let(red_ok,red_gas)=call(&escrow,"trigger_earn_redeem",json!({}),&org,s.clone(),&n,0,300).await?;let ev=view(&escrow,"get_event",json!({}),&n).await?;ensure!(red_ok&&ev["earn_state"]=="Redeemed","redeem incomplete {ev}");
 let(settle_ok,settle_gas)=call(&escrow,"settle",json!({}),&org,s.clone(),&n,0,300).await?;let result=json!({"status":if settle_ok {"PASS_LOCAL"} else {"FAILED"},"scope":"sandbox; patched account bootstrap only, no financial state patch; MockEarn zero yield","metadata_bytes":{"event_id":128,"commitment_id":128,"account_id":64,"title":256,"location":512,"rules_text":8192},"initial_account":before.data,"after_create":initial.data,"samples":samples,"finalize_gas":final_gas,"redeem_gas":red_gas,"settle_gas":settle_gas,"settle_success":settle_ok});println!("{}",serde_json::to_string_pretty(&result)?);ensure!(settle_ok,"settlement failed");Ok(())
}
